'use strict';
const assert=require('node:assert/strict'),{performance}=require('node:perf_hooks');
const Evidence=require('../engines/evidence.js');
global.MSOSEngines={Evidence};
require('../engines/evidence-index.js');
const athletes=Array.from({length:70},(_,i)=>({id:`a${i}`,full_name:`Swimmer ${i}`,sex:i%2?'F':'M',squad:i<30?'National':'Development'}));
const strokes=['Freestyle','Backstroke','Breaststroke','Butterfly','IM'];
const distances=[50,100,200,400,800,1500];
const rows=[];
for(let i=0;i<athletes.length;i++)for(let j=0;j<84;j++)rows.push({id:`r${i}-${j}`,athlete_id:athletes[i].id,distance:distances[j%distances.length],stroke:strokes[j%strokes.length],course:'SCM',result_seconds:25+(i%11)+(j%17)*3,wa_points:350+((i*17+j*13)%500)});
const state={athletes,resultsPbBoard:rows,resultsEventHistory:rows.slice(0,1800).map((r,i)=>({...r,id:`h${i}`})),coachResults:rows.slice(0,900).map((r,i)=>({...r,id:`c${i}`})),adaptationOverrides:[],settings:{view:'board',storageRevision:1},_refs:{}};
global.MSOS4={state,pathway:{isPara:()=>false,points:(_a,r)=>({value:r.wa_points,label:'WA',source:'stored'})},waPointsEngine:{tableInfo:()=>({}),equivalentTime:()=>null}};
const RacePace=require('../engines/race-pace.js');global.MSOSEngines.RacePace=RacePace;
require('../engines/performance.js');
const P=global.MSOS4.performanceEngine,session={id:'stress',identity:{course:'SCM'}},group=athletes.slice(0,17);
const t0=performance.now();
const out=group.map(a=>P.selectStrokeForContext(a,{raw:'#1 Stroke'},state,session,{}));
const elapsed=performance.now()-t0;
assert.equal(out.length,17);assert.ok(out.every(x=>x&&typeof x.stroke==='string'),'all deck swimmers must resolve without blocking/deep fallback');
assert.ok(elapsed<750,`17-swimmer deck evidence resolution took ${elapsed.toFixed(1)}ms on indexed large fixture`);
const t1=performance.now();group.forEach(a=>P.selectStrokeForContext(a,{raw:'#1 Stroke'},state,session,{}));const cached=performance.now()-t1;
assert.ok(cached<100,`cached 17-swimmer deck evidence resolution took ${cached.toFixed(1)}ms`);
console.log(`DECK_LARGE_EVIDENCE_LATENCY_PASS first=${elapsed.toFixed(1)}ms cached=${cached.toFixed(1)}ms rows=${rows.length+2700}`);
